//! Tree and code vectors, generated by `scripts/cpp_vectors/tree_code_vectors.cpp`.

use std::collections::{BTreeMap, HashMap};

use fp_core::code::code::{
    code_ok, factors, generator_at, generator_row, message_scale, symbol_at, tail_scale, Code,
    Encoder,
};
use fp_core::code::cosets::{gl64_point, gl64_subgroup_log, gl64_table};
use fp_core::code::short_position::short_position;
use fp_core::field::ext::{F, E};
use fp_core::hash::calls::HashCalls;
use fp_core::hash::modes::Digest;
use fp_core::iop::message::{Reader, Writer};
use fp_core::tree::opening::{
    check_opening, opening_bytes, opening_given, oracle_leaf, read_opening, write_opening,
    Opening, OracleTreeShape,
};
use fp_core::tree::positions::PositionList;
use fp_core::tree::tree::TreeValues;

const VECTORS: &str = include_str!("../../fixtures/tree_code_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn digest(s: &str) -> Digest {
    assert_eq!(s.len(), 64, "digest {}", s);
    let mut d = Digest::zero();
    for i in 0..8 {
        d.w[i] = u32::from_str_radix(&s[8 * i..8 * i + 8], 16).unwrap();
    }
    d
}

fn f(s: &str) -> F {
    F(u64::from_str_radix(s, 16).unwrap())
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([f(p[0]), f(p[1]), f(p[2])])
}

fn hex_bytes(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn flist(s: &str) -> Vec<F> {
    if s == "-" {
        return Vec::new();
    }
    s.split(',').map(f).collect()
}

fn shape_from(kv: &HashMap<&str, &str>) -> OracleTreeShape {
    let mut s = OracleTreeShape {
        log_n: kv["log_n"].parse().unwrap(),
        log_n_zk: kv["log_n_zk"].parse().unwrap(),
        main_symbols: vec![kv["main"].parse().unwrap()],
        mask_symbols: vec![kv["mask"].parse().unwrap()],
        tree_number: kv["tree_number"].parse().unwrap(),
        salt_bytes: kv["salt_bytes"].parse().unwrap(),
        stored: false,
        run: digest(kv["run"]),
        parameters: digest(kv["params"]),
    };
    if s.main_symbols == [0] {
        s.main_symbols.clear();
    }
    if s.mask_symbols == [0] {
        s.mask_symbols.clear();
    }
    s
}

struct Pending {
    ci: usize,
    li: usize,
    draws: Vec<u64>,
    log_n: u32,
    given: usize,
    gn: usize,
    read: bool,
    at_end: bool,
    check: bool,
    clash: bool,
    vertices: usize,
    entered: u64,
}

struct TreeData {
    shape: OracleTreeShape,
    root: Digest,
    cols: BTreeMap<u64, (Vec<F>, Vec<u8>, Digest)>,
}

#[test]
fn tree_vectors_match_the_cpp_reference() {
    let mut trees: HashMap<usize, TreeData> = HashMap::new();
    let mut pending: Option<Pending> = None;
    let mut records: HashMap<usize, TreeValues> = HashMap::new();
    let mut record_results: HashMap<usize, (bool, bool, usize, u64)> = HashMap::new();
    let mut last_for_tamper: Option<(OracleTreeShape, PositionList, Opening, Digest)> = None;
    let mut lines = 0usize;
    let mut checks = 0usize;

    for line in VECTORS.lines() {
        lines += 1;
        let first = line.split_whitespace().next().unwrap();
        if !first.starts_with("TREE")
            && !first.starts_with("COLS")
            && !first.starts_with("LIST")
            && !first.starts_with("OPENING")
            && first != "RECORD"
            && first != "RECORD_TAMPER"
            && !first.starts_with("CODE")
            && !first.starts_with("AT")
            && !first.starts_with("ENC_F")
            && !first.starts_with("ENC_E")
            && !first.starts_with("TABLE")
            && !first.starts_with("SHORT")
        {
            panic!("line {}: unknown tag {}", lines, first);
        }
        let kv = fields(line);
        if let Some(suffix) = first.strip_prefix("TREE") {
            let ci: usize = suffix.parse().unwrap();
            let shape = shape_from(&kv);
            assert!(shape.valid(), "line {}: shape invalid", lines);
            trees.insert(
                ci,
                TreeData { shape, root: digest(kv["root"]), cols: BTreeMap::new() },
            );
        } else if let Some(suffix) = first.strip_prefix("COLS") {
            let ci: usize = suffix.parse().unwrap();
            let pos: u64 = kv["pos"].parse().unwrap();
            let cols = flist(kv["f"]);
            let salt = hex_bytes(kv["salt"]);
            let leaf = digest(kv["leaf"]);
            let t = trees.get_mut(&ci).unwrap();
            assert_eq!(cols.len(), t.shape.width());
            assert_eq!(salt.len(), t.shape.salt_bytes);
            assert_eq!(
                oracle_leaf(&t.shape, pos, &cols, cols.len(), &salt, &mut HashCalls::new()),
                leaf,
                "line {}: leaf",
                lines
            );
            t.cols.insert(pos, (cols, salt, leaf));
        } else if let Some(suffix) = first.strip_prefix("LIST") {
            let ci: usize = suffix.parse().unwrap();
            let draws: Vec<u64> = kv["draws"].split(',').map(|x| x.parse().unwrap()).collect();
            pending = Some(Pending {
                ci,
                li: kv["i"].parse().unwrap(),
                draws,
                log_n: kv["log_n"].parse().unwrap(),
                given: kv["given"].parse().unwrap(),
                gn: kv["gn"].parse().unwrap(),
                read: kv["read"] == "1",
                at_end: kv["at_end"] == "1",
                check: kv["check"] == "1",
                clash: kv["clash"] == "1",
                vertices: kv["vertices"].parse().unwrap(),
                entered: kv["entered"].parse().unwrap(),
            });
        } else if let Some(suffix) = first.strip_prefix("OPENING") {
            let ci: usize = suffix.parse().unwrap();
            let li: usize = kv["i"].parse().unwrap();
            let p = pending.take().unwrap();
            assert_eq!((p.ci, p.li), (ci, li), "line {}: pending list", lines);
            let hex = line.split_whitespace().last().unwrap();
            let bytes = hex_bytes(hex);
            let data = trees.get(&ci).unwrap();
            assert_eq!(p.log_n, data.shape.log_n);
            let list = PositionList::from_draws(p.draws.clone(), p.log_n);
            assert_eq!(opening_given(&data.shape, &list), p.gn, "line {}: given", lines);
            let want_bytes = opening_bytes(&data.shape, &list);
            assert_eq!(want_bytes, bytes.len(), "line {}: opening_bytes", lines);
            let mut r = Reader::new(&bytes);
            let mut o = Opening::default();
            assert_eq!(read_opening(&mut r, &data.shape, &list, &mut o), p.read);
            assert_eq!(r.at_end(), p.at_end);
            assert_eq!(o.given.len(), p.given);
            for (i, &pos) in list.all().iter().enumerate() {
                let (cols, _, _) = data.cols.get(&pos).unwrap();
                assert_eq!(o.column(i), &cols[..], "line {}: column", lines);
            }
            let mut w = Writer::default();
            write_opening(&mut w, &data.shape, &list, &o);
            assert_eq!(w.bytes(), &bytes[..], "line {}: opening bytes roundtrip", lines);
            let mut calls = HashCalls::new();
            if ci == 3 {
                let seen = records.entry(ci).or_default();
                let mut clash = false;
                let ok = check_opening(&data.root, &data.shape, &list, &o, Some(seen), Some(&mut clash), &mut calls);
                assert_eq!(ok, p.check, "line {}: check", lines);
                assert_eq!(clash, p.clash, "line {}: clash", lines);
                record_results.insert(li, (ok, clash, seen.vertices(), seen.entered()));
                last_for_tamper = Some((data.shape.clone(), list, o, data.root));
            } else {
                let mut seen = TreeValues::default();
                let mut clash = false;
                let ok = check_opening(&data.root, &data.shape, &list, &o, Some(&mut seen), Some(&mut clash), &mut calls);
                assert_eq!(ok, p.check, "line {}: check", lines);
                assert_eq!(clash, p.clash, "line {}: clash", lines);
                assert_eq!(seen.vertices(), p.vertices, "line {}: vertices", lines);
                assert_eq!(seen.entered(), p.entered, "line {}: entered", lines);
                checks += 1;
            }
        } else if first == "RECORD" {
            let li: usize = kv["i"].parse().unwrap();
            let got = record_results[&li];
            assert_eq!(got.0, kv["ok"] == "1", "line {}: record ok", lines);
            assert_eq!(got.1, kv["clash"] == "1", "line {}: record clash", lines);
            assert_eq!(got.2, kv["vertices"].parse::<usize>().unwrap(), "line {}: record vertices", lines);
            assert_eq!(got.3, kv["entered"].parse::<u64>().unwrap(), "line {}: record entered", lines);
            checks += 1;
        } else if first == "RECORD_TAMPER" {
            let (shape, list, mut o, root) = last_for_tamper.take().unwrap();
            o.columns[0].0 ^= 1;
            let seen = records.get_mut(&3).unwrap();
            let mut clash = false;
            let ok = check_opening(&root, &shape, &list, &o, Some(seen), Some(&mut clash), &mut HashCalls::new());
            assert_eq!(ok, kv["ok"] == "1", "line {}: tamper ok", lines);
            assert_eq!(clash, kv["clash"] == "1", "line {}: tamper clash", lines);
            assert_eq!(seen.vertices(), kv["vertices"].parse::<usize>().unwrap());
            assert_eq!(seen.entered(), kv["entered"].parse::<u64>().unwrap());
            checks += 1;
        }
    }
    assert!(lines > 0 && checks > 0);
}

fn elist(s: &str) -> Vec<E> {
    if s == "-" {
        return Vec::new();
    }
    s.split(';').map(e).collect()
}

#[test]
fn code_vectors_match_the_cpp_reference() {
    let mut codes: HashMap<usize, Code> = HashMap::new();
    let mut lines = 0usize;
    let mut ats = 0usize;
    let mut encs = 0usize;

    for line in VECTORS.lines() {
        let first = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        if first.strip_prefix("CODE").is_some() {
            let i: usize = kv["i"].parse().unwrap();
            let c = Code {
                log_n: kv["log_n"].parse().unwrap(),
                ell: kv["ell"].parse().unwrap(),
                r: kv["r"].parse().unwrap(),
            };
            assert_eq!(code_ok(&c), kv["ok"] == "1");
            codes.insert(i, c);
            lines += 1;
        } else if first.strip_prefix("AT").is_some() {
            let i: usize = kv["i"].parse().unwrap();
            let c = codes[&i];
            let pos: u64 = kv["pos"].parse().unwrap();
            assert_eq!(gl64_point(c.log_n, pos), f(kv["z"]).0, "point at line {}", line);

            let want_f = flist(kv["f"]);
            assert_eq!(want_f.len(), c.log_dim() as usize);
            let mut got_f = vec![F::zero(); 64];
            factors(&c, pos, c.log_dim(), &mut got_f);
            assert_eq!(&got_f[..want_f.len()], &want_f[..]);
            assert_eq!(message_scale(&c, &got_f), f(kv["ms"]));
            assert_eq!(tail_scale(&c, &got_f), f(kv["ts"]));

            let g = generator_at(&c, pos);
            assert_eq!(&g.f[..want_f.len()], &want_f[..]);

            let message: Vec<F> = (0..c.ell).map(|j| F(100 + j as u64)).collect();
            let tail: Vec<F> = (0..c.r).map(|j| F(200 + j as u64)).collect();
            let mut mrow = vec![F::zero(); c.ell];
            let mut trow = vec![F::zero(); c.r];
            generator_row(&c, pos, Some(&mut mrow), Some(&mut trow));
            assert_eq!(mrow, flist(kv["mrow"]));
            assert_eq!(trow, flist(kv["trow"]));
            assert_eq!(symbol_at(&c, pos, &message, &tail), f(kv["symf"]), "symbol at {}", line);

            let message_e: Vec<E> = (0..c.ell)
                .map(|j| E([F(300 + j as u64), F(400 + j as u64), F(500 + j as u64)]))
                .collect();
            let tail_e: Vec<E> = (0..c.r)
                .map(|j| E([F(600 + j as u64), F(700 + j as u64), F(800 + j as u64)]))
                .collect();
            assert_eq!(symbol_at(&c, pos, &message_e, &tail_e), e(kv["syme"]));
            ats += 1;
        } else if first.strip_prefix("ENC_F").is_some() {
            let i: usize = kv["i"].parse().unwrap();
            let c = codes[&i];
            let message: Vec<F> = (0..c.ell).map(|j| F(100 + j as u64)).collect();
            let tail: Vec<F> = (0..c.r).map(|j| F(200 + j as u64)).collect();
            let enc = Encoder::new(c);
            let mut word = vec![F::zero(); c.n() as usize];
            enc.encode(&message, &tail, &mut word);
            assert_eq!(word, flist(kv["word"]), "encode at line {}", line);
            let mut m2 = vec![F::zero(); c.ell];
            let mut t2 = vec![F::zero(); c.r];
            let ok = enc.decode(&word, &mut m2, &mut t2);
            assert_eq!(ok, kv["decode"] == "1");
            assert_eq!(m2, message);
            assert_eq!(t2, tail);
            encs += 1;
        } else if first.strip_prefix("ENC_E").is_some() {
            let i: usize = kv["i"].parse().unwrap();
            let c = codes[&i];
            let message: Vec<E> = (0..c.ell)
                .map(|j| E([F(300 + j as u64), F(400 + j as u64), F(500 + j as u64)]))
                .collect();
            let tail: Vec<E> = (0..c.r)
                .map(|j| E([F(600 + j as u64), F(700 + j as u64), F(800 + j as u64)]))
                .collect();
            let enc = Encoder::new(c);
            let mut word = vec![E::default(); c.n() as usize];
            enc.encode(&message, &tail, &mut word);
            assert_eq!(word, elist(kv["word"]), "encode E at line {}", line);
            let mut m2 = vec![E::default(); c.ell];
            let mut t2 = vec![E::default(); c.r];
            let ok = enc.decode(&word, &mut m2, &mut t2);
            assert_eq!(ok, kv["decode"] == "1");
            assert_eq!(m2, message);
            assert_eq!(t2, tail);
            encs += 1;
        } else if first.strip_prefix("TABLE").is_some() {
            let i: usize = kv["i"].parse().unwrap();
            let c = codes[&i];
            let want: Vec<u64> = kv["v"]
                .split(',')
                .map(|x| u64::from_str_radix(x, 16).unwrap())
                .collect();
            let got = gl64_table(c.log_n, gl64_subgroup_log(c.log_n));
            assert_eq!(got, want, "transform table at line {}", line);
        } else if first.strip_prefix("SHORT").is_some() {
            let log_n: u32 = kv["log_n"].parse().unwrap();
            let log_short: u32 = kv["log_short"].parse().unwrap();
            let x: u64 = kv["x"].parse().unwrap();
            assert_eq!(
                short_position(log_n, log_short, x),
                kv["v"].parse::<u64>().unwrap(),
                "short position at line {}",
                line
            );
        }
    }
    assert!(lines > 0 && ats > 0 && encs > 0);
}
